    }
    return nil
}
```

### MaxBlobsPerBlock(slot) implementation:
```go
func (b *BeaconChainConfig) MaxBlobsPerBlock(slot primitives.Slot) int {
    epoch := primitives.Epoch(slot.DivSlot(b.SlotsPerEpoch))
    if len(b.BlobSchedule) > 0 {
        // scan BlobSchedule in reverse for most-recent matching entry
        for i := len(b.BlobSchedule) - 1; i >= 0; i-- {
            if epoch >= b.BlobSchedule[i].Epoch {
                return int(b.BlobSchedule[i].MaxBlobsPerBlock)
            }
        }
    }
    if epoch >= b.ElectraForkEpoch {
        return b.DeprecatedMaxBlobsPerBlockElectra
    }
    return b.DeprecatedMaxBlobsPerBlock
}
```

### Related Code (verification/blob.go:BlobIndexInBounds):
```go
func (bv *ROBlobVerifier) BlobIndexInBounds() (err error) {
    defer bv.recordResult(RequireBlobIndexInBounds, &err)
    maxBlobsPerBlock := params.BeaconConfig().MaxBlobsPerBlock(bv.blob.Slot())
    if bv.blob.Index >= uint64(maxBlobsPerBlock) {
        return ErrBlobIndexInvalid
    }
    return nil
}
```

### BlobSchedule / NetworkScheduleEntry context:
- `DeprecatedMaxBlobsPerBlock` / `DeprecatedMaxBlobsPerBlockElectra` fields marked as deprecated
- Fulu uses `BlobSchedule` (dynamic epoch-indexed schedule)
- `MaxBlobsPerBlock(slot)` uses slot→epoch derived limit, checked at gossip validation time
- `validateDenebBeaconBlock` is called for ALL Deneb+ blocks (version >= Deneb)
- The function guards with `blk.Version() < version.Deneb` but does NOT check Fulu separately
- In Fulu, blocks are version.Fulu (not Deneb); `blk.Version() < version.Deneb` would be false for Fulu blocks too
- Question: for Fulu-version blocks, does `validateDenebBeaconBlock` still apply?

